package wiki.creeper.harbor.common.pack;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import org.jspecify.annotations.Nullable;

/**
 * Resource packs generated by other plugins (ModelEngine, BetterModel, ...) found in the plugins
 * folder, so they are merged without listing them in pack.merge (proposed).
 *
 * <p>A preset counts only when that plugin is installed (a stale folder of a removed plugin is not
 * merged) and one of its output paths holds a pack. When a plugin writes both a folder and a zip
 * (ModelEngine with zip on), the more recently written one is used.
 */
public final class PluginPacks {

    /**
     * @param plugin plugin name as in its plugin.yml
     * @param paths output paths relative to the plugins folder (folder or .zip)
     */
    public record Preset(String plugin, List<String> paths) {
        public Preset {
            paths = List.copyOf(paths);
        }
    }

    /** A detected plugin pack. */
    public record Found(String plugin, Path path) {}

    /** Default output locations of plugins that generate a resource pack. */
    public static final List<Preset> PRESETS =
            List.of(
                    new Preset(
                            "ModelEngine",
                            List.of("ModelEngine/resource pack", "ModelEngine/resource pack.zip")),
                    new Preset(
                            "BetterModel", List.of("BetterModel/build", "BetterModel/build.zip")),
                    new Preset("ItemsAdder", List.of("ItemsAdder/output/generated.zip")),
                    new Preset("Nexo", List.of("Nexo/pack/pack.zip")),
                    new Preset("Oraxen", List.of("Oraxen/pack/pack.zip")));

    private PluginPacks() {}

    /**
     * @param pluginsDir server plugins folder
     * @param installed whether a plugin with that name is installed
     * @return found packs in preset order
     */
    public static List<Found> detect(Path pluginsDir, Predicate<String> installed) {
        return detect(PRESETS, pluginsDir, installed);
    }

    static List<Found> detect(List<Preset> presets, Path pluginsDir, Predicate<String> installed) {
        List<Found> found = new ArrayList<>();
        for (Preset preset : presets) {
            if (!installed.test(preset.plugin())) {
                continue;
            }
            @Nullable Path best = null;
            long bestTime = Long.MIN_VALUE;
            for (String rel : preset.paths()) {
                Path path = pluginsDir.resolve(rel);
                if (!looksLikePack(path)) {
                    continue;
                }
                long time = PackWatch.lastModified(path);
                if (best == null || time > bestTime) {
                    best = path;
                    bestTime = time;
                }
            }
            if (best != null) {
                found.add(new Found(preset.plugin(), best));
            }
        }
        return found;
    }

    /** A .zip file, or a folder with assets at its root or one level in. */
    static boolean looksLikePack(Path path) {
        if (Files.isRegularFile(path)) {
            return String.valueOf(path.getFileName())
                    .toLowerCase(java.util.Locale.ROOT)
                    .endsWith(".zip");
        }
        if (!Files.isDirectory(path)) {
            return false;
        }
        try {
            PackSource.folderRoot(path);
            return true;
        } catch (IOException e) {
            return false;
        }
    }
}
